<script setup lang="ts">
import { reactive, ref, watch } from 'vue'; import * as errorAPI from '@shared-api/admin/errorPassthrough'; import type { ErrorPassthroughRule } from '@shared-api/admin/errorPassthrough'; import * as tlsAPI from '@shared-api/admin/tlsFingerprintProfile'; import type { TLSFingerprintProfile } from '@shared-api/admin/tlsFingerprintProfile'; import SurfaceDialog from '@/components/base/SurfaceDialog.vue'; import { DialogWidth } from '@/components/base/dialog'; import { splitValues } from '@/features/admin/resources/model'; import { ConfirmTone, useConfirmStore } from '@/stores/confirm'; import { useAppStore } from '@/stores/app'
enum CatalogTab { ERRORS = 'errors', TLS = 'tls' }
const props = defineProps<{ show: boolean }>(); const emit = defineEmits<{ close: [] }>(); const app = useAppStore(); const confirm = useConfirmStore(); const tab = ref(CatalogTab.ERRORS); const errors = ref<ErrorPassthroughRule[]>([]); const profiles = ref<TLSFingerprintProfile[]>([]); const loading = ref(false); const saving = ref(false); const editErrorId = ref<number | null>(null); const editTlsId = ref<number | null>(null)
const errorForm = reactive({ name: '', enabled: true, priority: 0, error_codes: '', keywords: '', match_mode: 'any', platforms: '', passthrough_code: true, response_code: '' as number | string, passthrough_body: true, custom_message: '', skip_monitoring: false, description: '' })
const tlsForm = reactive({ name: '', description: '', enable_grease: true, cipher_suites: '', curves: '', point_formats: '', signature_algorithms: '', alpn_protocols: 'h2,http/1.1', supported_versions: '', key_share_groups: '', psk_modes: '', extensions: '' })
function numberList(value: string): number[] { const items = splitValues(value).map(Number); if (items.some(item => !Number.isInteger(item) || item < 0)) throw new Error('TLS 数值列表必须是非负整数'); return items }
async function load(): Promise<void> { loading.value = true; try { if (tab.value === CatalogTab.ERRORS) errors.value = await errorAPI.list(); else profiles.value = await tlsAPI.list() } catch (caught) { app.showError((caught as { message?: string }).message || '运行时配置加载失败') } finally { loading.value = false } }
function resetError(): void { editErrorId.value = null; Object.assign(errorForm, { name: '', enabled: true, priority: 0, error_codes: '', keywords: '', match_mode: 'any', platforms: '', passthrough_code: true, response_code: '', passthrough_body: true, custom_message: '', skip_monitoring: false, description: '' }) }
async function editError(rule: ErrorPassthroughRule): Promise<void> { const value = await errorAPI.getById(rule.id); editErrorId.value = value.id; Object.assign(errorForm, { ...value, error_codes: value.error_codes.join(','), keywords: value.keywords.join('\n'), platforms: value.platforms.join(','), response_code: value.response_code ?? '', custom_message: value.custom_message || '', description: value.description || '' }) }
async function saveError(): Promise<void> { if (!errorForm.name.trim()) { app.showError('规则名称不能为空'); return } saving.value = true; try { const payload = { name: errorForm.name.trim(), enabled: errorForm.enabled, priority: errorForm.priority, error_codes: numberList(errorForm.error_codes), keywords: splitValues(errorForm.keywords), match_mode: errorForm.match_mode as 'any' | 'all', platforms: splitValues(errorForm.platforms), passthrough_code: errorForm.passthrough_code, response_code: errorForm.response_code === '' ? null : Number(errorForm.response_code), passthrough_body: errorForm.passthrough_body, custom_message: errorForm.custom_message.trim() || null, skip_monitoring: errorForm.skip_monitoring, description: errorForm.description.trim() || null }; if (editErrorId.value) await errorAPI.update(editErrorId.value, payload); else await errorAPI.create(payload); app.showSuccess('错误透传规则已保存'); resetError(); await load() } catch (caught) { app.showError((caught as { message?: string }).message || '保存失败') } finally { saving.value = false } }
async function deleteError(rule: ErrorPassthroughRule): Promise<void> { if (!await confirm.ask({ title: '删除错误透传规则', message: `确认删除 ${rule.name}？`, confirmText: '删除', tone: ConfirmTone.DANGER })) return; await errorAPI.deleteRule(rule.id); app.showSuccess('规则已删除'); await load() }
function resetTls(): void { editTlsId.value = null; Object.assign(tlsForm, { name: '', description: '', enable_grease: true, cipher_suites: '', curves: '', point_formats: '', signature_algorithms: '', alpn_protocols: 'h2,http/1.1', supported_versions: '', key_share_groups: '', psk_modes: '', extensions: '' }) }
async function editTls(profile: TLSFingerprintProfile): Promise<void> { const value = await tlsAPI.getById(profile.id); editTlsId.value = value.id; Object.assign(tlsForm, { name: value.name, description: value.description || '', enable_grease: value.enable_grease, cipher_suites: value.cipher_suites.join(','), curves: value.curves.join(','), point_formats: value.point_formats.join(','), signature_algorithms: value.signature_algorithms.join(','), alpn_protocols: value.alpn_protocols.join(','), supported_versions: value.supported_versions.join(','), key_share_groups: value.key_share_groups.join(','), psk_modes: value.psk_modes.join(','), extensions: value.extensions.join(',') }) }
async function saveTls(): Promise<void> { if (!tlsForm.name.trim()) { app.showError('指纹档案名称不能为空'); return } saving.value = true; try { const payload = { name: tlsForm.name.trim(), description: tlsForm.description.trim() || null, enable_grease: tlsForm.enable_grease, cipher_suites: numberList(tlsForm.cipher_suites), curves: numberList(tlsForm.curves), point_formats: numberList(tlsForm.point_formats), signature_algorithms: numberList(tlsForm.signature_algorithms), alpn_protocols: splitValues(tlsForm.alpn_protocols), supported_versions: numberList(tlsForm.supported_versions), key_share_groups: numberList(tlsForm.key_share_groups), psk_modes: numberList(tlsForm.psk_modes), extensions: numberList(tlsForm.extensions) }; if (editTlsId.value) await tlsAPI.update(editTlsId.value, payload); else await tlsAPI.create(payload); app.showSuccess('TLS 指纹档案已保存'); resetTls(); await load() } catch (caught) { app.showError((caught as { message?: string }).message || '保存失败') } finally { saving.value = false } }
async function deleteTls(profile: TLSFingerprintProfile): Promise<void> { if (!await confirm.ask({ title: '删除 TLS 指纹档案', message: `确认删除 ${profile.name}？已引用时后端会拒绝。`, confirmText: '删除', tone: ConfirmTone.DANGER })) return; await tlsAPI.deleteProfile(profile.id); app.showSuccess('指纹档案已删除'); await load() }
watch(() => props.show, (show) => { if (show) { tab.value = CatalogTab.ERRORS; resetError(); resetTls(); void load() } }); watch(tab, () => { resetError(); resetTls(); void load() })
</script>
<template><SurfaceDialog :show="show" title="运行时规则库" description="错误透传与 TLS 指纹是账号调度的共享配置，可在账号 Extra 中按 ID 或策略引用。" :width="DialogWidth.WIDE" @close="emit('close')"><div class="resource-form-stack"><div class="resource-tabs"><button :aria-selected="tab === CatalogTab.ERRORS" @click="tab = CatalogTab.ERRORS">错误透传</button><button :aria-selected="tab === CatalogTab.TLS" @click="tab = CatalogTab.TLS">TLS 指纹</button></div>
  <template v-if="tab === CatalogTab.ERRORS"><fieldset class="resource-form-section"><legend>{{ editErrorId ? '编辑规则' : '新增规则' }}</legend><div class="resource-form-grid resource-form-grid--3"><label class="resource-field--wide">名称<input v-model="errorForm.name" /></label><label>优先级<input v-model.number="errorForm.priority" type="number" /></label><label>匹配模式<select v-model="errorForm.match_mode"><option value="any">任一</option><option value="all">全部</option></select></label><label>响应码<input v-model="errorForm.response_code" type="number" min="100" max="599" placeholder="沿用上游" /></label><label class="resource-field--wide">错误码（逗号）<input v-model="errorForm.error_codes" /></label><label class="resource-field--wide">关键词（逗号或换行）<textarea v-model="errorForm.keywords" rows="3" /></label><label class="resource-field--wide">平台<input v-model="errorForm.platforms" /></label><label class="resource-check"><input v-model="errorForm.enabled" type="checkbox" /><span>启用</span></label><label class="resource-check"><input v-model="errorForm.passthrough_code" type="checkbox" /><span>透传状态码</span></label><label class="resource-check"><input v-model="errorForm.passthrough_body" type="checkbox" /><span>透传响应体</span></label><label class="resource-check"><input v-model="errorForm.skip_monitoring" type="checkbox" /><span>跳过监控计数</span></label><label class="resource-field--wide">自定义消息<input v-model="errorForm.custom_message" /></label><label class="resource-field--wide">描述<textarea v-model="errorForm.description" rows="2" /></label></div><div class="resource-inline-actions"><button class="resource-button" :disabled="saving" @click="saveError">保存规则</button><button v-if="editErrorId" class="resource-button resource-button--secondary" @click="resetError">取消编辑</button></div></fieldset><div class="resource-table"><table><thead><tr><th>规则</th><th>优先级</th><th>匹配</th><th>行为</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="6">加载中…</td></tr><tr v-for="rule in errors" :key="rule.id"><td>{{ rule.name }}<small>{{ rule.description || '无描述' }}</small></td><td>{{ rule.priority }}</td><td>{{ rule.error_codes.join(', ') }}<small>{{ rule.keywords.join(' / ') }}</small></td><td>{{ rule.passthrough_code ? '透传码' : rule.response_code }} · {{ rule.passthrough_body ? '透传体' : '自定义体' }}</td><td><button class="resource-link" @click="errorAPI.toggleEnabled(rule.id, !rule.enabled).then(load)">{{ rule.enabled ? '启用' : '停用' }}</button></td><td><button class="resource-link" @click="editError(rule)">编辑</button><button class="resource-link resource-link--danger" @click="deleteError(rule)">删除</button></td></tr></tbody></table></div></template>
  <template v-else><fieldset class="resource-form-section"><legend>{{ editTlsId ? '编辑档案' : '新增档案' }}</legend><div class="resource-form-grid resource-form-grid--3"><label class="resource-field--wide">名称<input v-model="tlsForm.name" /></label><label class="resource-field--wide">描述<textarea v-model="tlsForm.description" rows="2" /></label><label class="resource-check"><input v-model="tlsForm.enable_grease" type="checkbox" /><span>启用 GREASE</span></label><label v-for="field in ['cipher_suites','curves','point_formats','signature_algorithms','supported_versions','key_share_groups','psk_modes','extensions']" :key="field">{{ field }}<input v-model="tlsForm[field as keyof typeof tlsForm]" /></label><label class="resource-field--wide">ALPN 协议<input v-model="tlsForm.alpn_protocols" /></label></div><div class="resource-inline-actions"><button class="resource-button" :disabled="saving" @click="saveTls">保存档案</button><button v-if="editTlsId" class="resource-button resource-button--secondary" @click="resetTls">取消编辑</button></div></fieldset><div class="resource-table"><table><thead><tr><th>档案</th><th>GREASE</th><th>Ciphers</th><th>Curves</th><th>ALPN</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="6">加载中…</td></tr><tr v-for="profile in profiles" :key="profile.id"><td>{{ profile.name }}<small>#{{ profile.id }} · {{ profile.description || '无描述' }}</small></td><td>{{ profile.enable_grease ? '启用' : '关闭' }}</td><td>{{ profile.cipher_suites.length }}</td><td>{{ profile.curves.length }}</td><td>{{ profile.alpn_protocols.join(', ') }}</td><td><button class="resource-link" @click="editTls(profile)">编辑</button><button class="resource-link resource-link--danger" @click="deleteTls(profile)">删除</button></td></tr></tbody></table></div></template>
  </div></SurfaceDialog></template>
